command: echo -e '# Adaptive Rejection Sampling implementation

# Auxiliary function for numerical derivative
hprime <- function(logdens, x, eps = 1e-6, lower, upper) {
  eps_l <- eps
  eps_r <- eps
  if (is.finite(lower) && x - eps_l < lower) eps_l <- x - lower
  if (is.finite(upper) && x + eps_r > upper) eps_r <- upper - x
  if (eps_l > 0 && eps_r > 0) {
    return( (logdens(x + eps_r) - logdens(x - eps_l)) / (eps_r + eps_l) )
  } else if (eps_r > 0) {
    return( (logdens(x + eps_r) - logdens(x)) / eps_r )
  } else if (eps_l > 0) {
    return( (logdens(x) - logdens(x - eps_l)) / eps_l )
  } else {
    stop("Cannot compute derivative at boundary")
  }
}
' > /app/ars.R
